export const meta = {
  name: 'shelf-stage2-features-f2-f5',
  description: 'Stage 2: F2+F5 (report.py), F3 (cli --version), F4 (export.py) in parallel on disjoint files',
  phases: [{ title: 'Implement features' }],
}
phase('Implement features')
const common = `Repo: current working directory (Python package "shelf", in-memory catalogue in shelf/books.py with add/find/all_books/clear; tests via \`python -m pytest -q\`). Other agents are editing other files concurrently — touch ONLY the files named below. Do not edit TICKETS.md, tests/test_books.py or tests/test_bugs.py, and do not commit. Match the existing minimal style. Run python -m pytest -q on your test file and report the files changed and the final pytest summary line.`
const tasks = [
  { label: 'F2+F5:report', prompt: `${common}
Files: shelf/report.py, new tests/test_report.py.
- F2: add report.by_author() returning a dict {author: count} over books.all_books() (empty dict for an empty shelf).
- F5: add report.as_json() returning a JSON string (json.dumps) with the summary and per-author counts, e.g. {"summary": summary(), "by_author": by_author()}. Must work on an empty shelf.
Keep summary() unchanged. Tests should use setup_function calling books.clear().` },
  { label: 'F3:cli-version', prompt: `${common}
Files: shelf/cli.py, new tests/test_cli.py.
- F3: \`python -m shelf --version\` prints exactly \`shelf 0.1.0\` and exits 0. Define __version__ = "0.1.0" in shelf/cli.py (do NOT edit shelf/__init__.py) and use argparse action="version" with version="%(prog)s " + __version__. Subcommands stay required otherwise. Test via main(["--version"]) catching SystemExit and checking capsys output.` },
  { label: 'F4:export-csv', prompt: `${common}
Files: new shelf/export.py, new tests/test_export.py.
- F4: export_csv() returns a CSV string (use the csv module with io.StringIO, lineterminator "\\n") of every book from books.all_books(), with header row \`title,author\`. Empty shelf returns just the header line. Test commas/quotes in titles are quoted correctly. Tests use setup_function calling books.clear().` },
]
const results = await parallel(tasks.map(t => () => agent(t.prompt, { label: t.label, effort: 'low' })))
return tasks.map((t, i) => ({ ticket: t.label, result: results[i] }))

